mapper.select:
SELECT m.method_id AS "methodId"
     , m.is_synthetic AS "isSynthetic"
     , m.return_type AS "returnType"
  FROM analysis_method m
  JOIN analysis_symbol s ON s.revision_id = m.revision_id AND s.symbol_id = m.owner_symbol_id
 WHERE m.revision_id = #{revisionId}
   AND s.fqn = #{ownerFqn}
   AND m.name = #{name}
AND m.param_count = #{paramCount}
 ORDER BY m.method_id
 LIMIT 10

SELECT f.field_id
  FROM analysis_field f
  JOIN analysis_symbol s ON s.revision_id = f.revision_id AND s.symbol_id = f.owner_symbol_id
 WHERE f.revision_id = #{revisionId}
   AND s.fqn = #{ownerFqn}
   AND f.name = #{name}
 ORDER BY f.field_id
 LIMIT 1

SELECT f.type
  FROM analysis_field f
  JOIN analysis_symbol s ON s.revision_id = f.revision_id AND s.symbol_id = f.owner_symbol_id
 WHERE f.revision_id = #{revisionId}
   AND s.fqn = #{ownerFqn}
   AND f.name = #{name}
   AND f.is_synthetic
 LIMIT 1

SELECT method_id
  FROM analysis_method
 WHERE revision_id = #{revisionId}
   AND name = #{name}
   AND NOT is_constructor
AND param_count = #{paramCount}
 ORDER BY method_id
 LIMIT #{limit}

SELECT symbol_id AS "symbolId", fqn AS "fqn", kind AS "kind"
  FROM analysis_symbol
 WHERE revision_id = #{revisionId}
   AND simple_name = #{simpleName}
   AND kind <> 'ANONYMOUS'
 ORDER BY symbol_id
 LIMIT #{limit}
